class Solution {
public:
    vector<int> sortedSquares(vector<int>& nums) {
        int n = nums.size();
        vector<int> res(n);
        int l = 0, r = n - 1;
        for (int w = n - 1; w >= 0; w--) {
            if (abs(nums[l]) > abs(nums[r])) {
                res[w] = nums[l] * nums[l];
                l++;
            } else {
                res[w] = nums[r] * nums[r];
                r--;
            }
        }
        return res;
    }
};
